WITH cleaned AS (SELECT id, method, paid_at, status, DATE_FORMAT(paid_at, 'yyyy-MM') AS paid_at_label, DATE_FORMAT(paid_at, 'yyyy-MM-dd') AS paid_at_label_2, COALESCE(method, 'NONE') AS method_clean FROM payments WHERE method IS DISTINCT FROM 'promptpay' AND paid_at > TIMESTAMP '2023-09-14 10:00:00'), valid AS (SELECT *, DATEDIFF(CURRENT_DATE(), paid_at) AS days_since_paid_at, CONCAT_WS('-', method, status) AS method_status_key FROM cleaned WHERE method IS NOT NULL), with_windows AS (SELECT *, SUM(days_since_paid_at) OVER (PARTITION BY MONTH(paid_at), status ORDER BY days_since_paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_days_since_paid_at, LAG(days_since_paid_at, 1) OVER (PARTITION BY method, status ORDER BY paid_at, id) AS prev_days_since_paid_at, SUM(days_since_paid_at) OVER w_hist AS running_days_since_paid_at_2, COUNT(days_since_paid_at) OVER w_running AS method_count_days_since_paid_at FROM valid WINDOW w_hist AS (PARTITION BY MONTH(paid_at) ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_running AS (PARTITION BY method)), metrics AS (SELECT id, paid_at_label, paid_at_label_2, method_clean, days_since_paid_at, running_days_since_paid_at, running_days_since_paid_at_2, method_count_days_since_paid_at, AVG(running_days_since_paid_at) OVER (PARTITION BY status, method ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS running_days_since_paid_at_avg_7d, NTILE(10) OVER (ORDER BY prev_days_since_paid_at DESC, id) AS prev_days_since_paid_at_bucket FROM with_windows WHERE method <> 'promptpay') SELECT CASE WHEN running_days_since_paid_at_2 >= 367 THEN 'PREMIUM' ELSE 'STANDARD' END AS running_days_since_paid_at_2_tier, AVG(prev_days_since_paid_at_bucket) AS avg_prev_days_since_paid_at_bucket, PERCENTILE_APPROX(method_count_days_since_paid_at, ARRAY(0.25, 0.5, 0.75)) AS method_count_days_since_paid_at_quartiles, ROUND(AVG(running_days_since_paid_at), 2) AS avg_running_days_since_paid_at FROM metrics GROUP BY CASE WHEN running_days_since_paid_at_2 >= 367 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY avg_running_days_since_paid_at NULLS LAST
